.wc-pilot-root .wc-pilot-rainbow-science-grid span{margin-top:6px}
.wc-pilot-root .wc-pilot-rainbow-science-note{margin-top:12px;font-size:13px;line-height:1.65;color:var(--wc-pilot-muted)}
.wc-pilot-root .wc-pilot-rainbow-science :is(strong,span,p,summary){overflow-wrap:normal;word-break:normal}
