    if (wcFiveStyle) wcFiveStyle.textContent += ".wc-hydro-quest{--wc-hydro-paper:#eef7f4;--wc-hydro-card:#ffffff;--wc-hydro-ink:#123f37;--wc-hydro-muted:#385e55;--wc-hydro-line:#98bdb1;--wc-hydro-accent:#176450;--wc-hydro-complete:#ddf2e6;container:wc-hydro-quest / inline-size;margin:0 0 16px;padding:18px;border:1px solid var(--wc-hydro-line);border-radius:18px;background:var(--wc-hydro-paper);color:var(--wc-hydro-ink);box-shadow:0 8px 24px rgba(18,63,55,.06)}
.wc-hydro-quest[data-wc-hydro-theme=dark]{--wc-hydro-paper:#102c29;--wc-hydro-card:#173b35;--wc-hydro-ink:#f0fdf4;--wc-hydro-muted:#c2e2d5;--wc-hydro-line:#648d7f;--wc-hydro-accent:#88e1bc;--wc-hydro-complete:#214b3c;background:var(--wc-hydro-paper)}
.wc-hydro-quest .wc-hydro-head{align-items:center;gap:16px;flex-wrap:wrap;margin-bottom:14px}
.wc-hydro-quest .wc-hydro-kicker{font-size:13px;line-height:1.5;letter-spacing:.06em;color:var(--wc-hydro-muted)}
.wc-hydro-quest .wc-hydro-head .wc-hydro-rank{margin:4px 0 0;font-size:24px;line-height:1.45;font-weight:900;color:var(--wc-hydro-ink)}
.wc-hydro-quest .wc-hydro-score{padding:8px 12px;border:1px solid var(--wc-hydro-line);border-radius:12px;background:var(--wc-hydro-card);color:var(--wc-hydro-ink);font-size:22px;line-height:1.4;white-space:nowrap;font-variant-numeric:tabular-nums}
.wc-hydro-quest .wc-hydro-progress{height:12px;margin:0 0 16px;border:1px solid var(--wc-hydro-line);border-radius:999px;background:var(--wc-hydro-card)}
.wc-hydro-quest .wc-hydro-progress>span{height:100%;border-radius:inherit;background:var(--wc-hydro-accent);transition:none}
.wc-hydro-quest #wcHydroQuestStatus{position:static;width:auto;height:auto;margin:0 0 14px;padding:0;overflow:visible;clip:auto;clip-path:none;white-space:normal;font-size:13px;line-height:1.6;color:var(--wc-hydro-muted)}
.wc-hydro-quest .wc-hydro-missions{grid-template-columns:minmax(0,1fr);gap:12px}
.wc-hydro-quest .wc-hydro-mission{grid-template-columns:28px minmax(0,1fr);gap:8px 10px;align-items:start;min-width:0;padding:14px;border:1px solid var(--wc-hydro-line);border-radius:12px;background:var(--wc-hydro-card);color:var(--wc-hydro-ink)}
.wc-hydro-quest .wc-hydro-mission.is-complete{background:var(--wc-hydro-complete);border-color:var(--wc-hydro-accent)}
.wc-hydro-quest .wc-hydro-mark{display:grid;place-items:center;width:28px;height:28px;border:1px solid var(--wc-hydro-line);border-radius:50%;background:var(--wc-hydro-paper);color:var(--wc-hydro-ink);font-size:18px;line-height:1}
.wc-hydro-quest .wc-hydro-mission.is-complete .wc-hydro-mark{border-color:var(--wc-hydro-accent);color:var(--wc-hydro-ink)}
.wc-hydro-quest .wc-hydro-mission>span:nth-child(2){min-width:0}
.wc-hydro-quest .wc-hydro-mission strong{display:block;font-size:15px;line-height:1.5;color:var(--wc-hydro-ink);overflow-wrap:normal;word-break:normal}
.wc-hydro-quest .wc-hydro-mission small{display:block;margin-top:4px;font-size:13px;line-height:1.6;color:var(--wc-hydro-muted);overflow-wrap:normal;word-break:normal}
.wc-hydro-quest .wc-hydro-state{grid-column:2;justify-self:start;padding:3px 8px;border:1px solid var(--wc-hydro-line);border-radius:999px;background:var(--wc-hydro-paper);color:var(--wc-hydro-ink);font-size:13px;line-height:1.5;font-weight:700}
@container wc-hydro-quest (min-width:560px){.wc-hydro-quest .wc-hydro-missions{grid-template-columns:repeat(2,minmax(0,1fr))}}
@container wc-hydro-quest (min-width:900px){.wc-hydro-quest .wc-hydro-missions{grid-template-columns:repeat(3,minmax(0,1fr))}}
@container wc-hydro-quest (max-width:280px){.wc-hydro-quest .wc-hydro-mission{padding:10px;gap:8px}.wc-hydro-quest .wc-hydro-head{gap:10px}.wc-hydro-quest .wc-hydro-head .wc-hydro-rank{font-size:21px}}
@media(forced-colors:active){.wc-hydro-quest,.wc-hydro-quest :is(.wc-hydro-score,.wc-hydro-mission,.wc-hydro-mark,.wc-hydro-state){background:Canvas;color:CanvasText;border-color:CanvasText;box-shadow:none}.wc-hydro-quest :is(.wc-hydro-kicker,.wc-hydro-head .wc-hydro-rank,.wc-hydro-mission strong,.wc-hydro-mission small,#wcHydroQuestStatus){color:CanvasText}.wc-hydro-quest .wc-hydro-progress{background:Canvas;border-color:CanvasText}.wc-hydro-quest .wc-hydro-progress>span{background:Highlight}.wc-hydro-quest .wc-hydro-mission.is-complete{border-style:double;border-width:3px}.wc-hydro-quest .wc-hydro-mission.is-complete .wc-hydro-mark{border-color:CanvasText}}";
